// This project uses custom actions/recognitions, not Agent event
// subscribers. Binding the Tasker also forwards every live-preview
// screencap. Maa 5.12 sends those events without consuming their
// replies, filling the channel while idle (~3000 frames). Resource
// binding retains callbacks and their reverse context/controller
// calls without adding the unused event stream.
var client = useTcp
    ? MaaAgentClient.CreateTcp(tasker.Resource)
    : MaaAgentClient.Create(identifier, tasker.Resource);
